{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시나 구청이 소공원·근린공원에 길고양이 급식소 설치 사업을 할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제22조제4항에 따르면, 시장 또는 구청장은 길고양이의 효과적인 개체수 조절과 쾌적한 도시 환경을 목적으로 「도시공원 및 녹지 등에 관한 법률」 제15조제1항제2호 생활공원 중 소공원 및 근린공원에 급식소를 설치할 수 있다. 따라서 서울시(시장)나 구청(구청장)은 해당 목적의 소공원·근린공원 길고양이 급식소 설치 사업을 할 수 있다.",
          "b_ids": "동물보호:제22조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
